import React,{useState,useCallback,useEffect} from 'react';
import {FlatList,Text,RefreshControl,View} from 'react-native';
export default function L(){
  const[d,setD]=useState<any[]>([]);const[r,setR]=useState(false);
  const load=useCallback(async()=>{setR(true);const x=await fetch('{{endpoint}}').then(r=>r.json());setD(x);setR(false);},[]);
  useEffect(()=>{load();},[load]);
  return(<FlatList data={d} keyExtractor={(_,i)=>String(i)} renderItem={({item})=>(<View style={{padding:16}}><Text>{item.title}</Text></View>)} refreshControl={<RefreshControl refreshing={r} onRefresh={load}/>}/>);}
